package testutil

import (
	"bytes"
	"compress/zlib"
	_ "embed"
	"encoding/binary"
	"image"
	"image/color"
	"image/png"

	"github.com/Wolfsblvt/smolpng/internal/jpegimage"
)

// profileSRGB was generated by LittleCMS through Pillow's createProfile("sRGB").
// Its copyright tag says "No copyright, use freely". This frozen control input
// shares the corpus's CC0 dedication; regeneration needs neither Pillow nor CMS.
//
//go:embed profile-srgb.icc
var profileSRGB []byte

// ICCProfile returns a complete RGB matrix profile, optionally exchanging the
// red/blue colorants. The latter is a synthetic control, not a real-world gamut:
// ignoring it or attaching it after sRGB conversion visibly swaps red and blue.
// Its inherited descriptive name is not a claim that the variant is sRGB.
func ICCProfile(swapped bool) []byte {
	profile := bytes.Clone(profileSRGB)
	if !swapped {
		return profile
	}
	var red, blue uint32
	count := binary.BigEndian.Uint32(profile[128:])
	for i := uint32(0); i < count; i++ {
		entry := profile[132+i*12:]
		switch string(entry[:4]) {
		case "rXYZ":
			red = binary.BigEndian.Uint32(entry[4:])
		case "bXYZ":
			blue = binary.BigEndian.Uint32(entry[4:])
		}
	}
	copy(profile[red:red+20], profileSRGB[blue:blue+20])
	copy(profile[blue:blue+20], profileSRGB[red:red+20])
	clear(profile[84:100]) // Do not retain a stale profile ID after changing tags.
	return profile
}

func iccSwatches(swapped bool) image.Image {
	m := image.NewNRGBA(image.Rect(0, 0, 144, 96))
	for y := 0; y < 96; y++ {
		for x := 0; x < 144; x++ {
			index := (y/8)*18 + x/8
			c := color.NRGBA{R: uint8(index%6) * 51, G: uint8(index/6%6) * 51, B: uint8(index/36%6) * 51, A: 255}
			if swapped {
				c.R, c.B = c.B, c.R
			}
			m.SetNRGBA(x, y, c)
		}
	}
	return m
}

// ICCCorpus supplies complete profiled PNG/JPEG inputs. Finite-color swatches
// can reach pngquant at ordinary quality without lowering production defaults.
func ICCCorpus() map[string][]byte {
	out := map[string][]byte{}
	for _, swapped := range []bool{false, true} {
		name := "srgb"
		if swapped {
			name = "swapped"
		}
		profile := ICCProfile(swapped)
		var compressed bytes.Buffer
		writer := zlib.NewWriter(&compressed)
		_, _ = writer.Write(profile)
		_ = writer.Close()
		payload := append([]byte("smolpng\x00\x00"), compressed.Bytes()...)
		out["icc-"+name+".png"] = AddChunk(PNG(iccSwatches(swapped), png.NoCompression), "iCCP", payload)
		base := JPEG(iccSwatches(swapped), 95)
		marker := jpegimage.Marker(0xe2, append([]byte("ICC_PROFILE\x00\x01\x01"), profile...))
		out["jpeg-icc-"+name+".jpg"] = append(append(bytes.Clone(base[:2]), marker...), base[2:]...)
	}
	return out
}
